/* ==========================================================================
 *  params.h  --  Todos los numeros sintonizables del robot, en un solo sitio
 *
 *  Por que un fichero aparte: en la bitacora de versiones, una iteracion de
 *  tipo "tuning" debe producir un diff de tres lineas legible de un vistazo.
 *  Si los numeros magicos viven dentro de strategy.c, el diff se vuelve ruido
 *  y se pierde el objetivo del proyecto: entender QUE toco la IA y POR QUE.
 *
 *  Regla de la bitacora: cambiar un numero de aqui = version "tuning" (patch).
 *  Anadir un campo nuevo = version "new-behavior" (minor).
 * ========================================================================== */
#ifndef SUMO_PARAMS_H
#define SUMO_PARAMS_H

#include <stdint.h>
#include "sumo_types.h"

/* Aperturas de partida. El primer segundo decide muchos combates. */
typedef enum {
  OPENING_CHARGE = 0,   /* embestida recta inmediata                        */
  OPENING_ARC_L  = 1,   /* arco a babor buscando el flanco del rival        */
  OPENING_ARC_R  = 2,   /* arco a estribor                                  */
  OPENING_SCAN   = 3    /* giro en el sitio hasta enganchar y luego atacar   */
} sumo_opening_t;

typedef struct {
  /* ---- periodo de control ------------------------------------------- */
  uint16_t dt_ms;                 /* periodo del lazo, ms                  */

  /* ---- percepcion ---------------------------------------------------- */
  uint16_t dist_valid_max_mm;     /* por encima, se ignora la lectura      */
  uint16_t dist_attack_mm;        /* rival "enganchado": empuje a fondo    */
  uint16_t dist_track_mm;         /* rival a la vista: persecucion         */
  uint16_t target_hold_ms;        /* histeresis: sigo creyendo que esta ahi*/

  /* ---- velocidades normalizadas [0..1] ------------------------------- */
  float v_attack;
  float v_track;
  float v_search;
  float v_escape;
  float v_opening;

  /* ---- seguimiento --------------------------------------------------- */
  float track_kp;                 /* rad^-1, error de rumbo -> diferencial */
  float track_max_diff;           /* tope del termino diferencial          */

  /* ---- escape de borde (maxima prioridad) ----------------------------- */
  uint16_t escape_back_ms;        /* retroceso tras ver linea frontal      */
  uint16_t escape_turn_ms;        /* giro de reencuadre                    */
  uint16_t escape_lockout_ms;     /* ventana ciega para no reentrar al borde*/

  /* ---- busqueda ------------------------------------------------------- */
  uint16_t search_spin_ms;        /* giro en el sitio                      */
  uint16_t search_probe_ms;       /* avance corto entre giros              */
  float    search_turn_ratio;     /* -1 = sobre si mismo, 0 = recto        */

  /* ---- apertura -------------------------------------------------------- */
  sumo_opening_t opening;
  uint16_t       opening_ms;      /* duracion de la apertura               */

  /* ---- proteccion del tren motriz -------------------------------------- */
  float slew_per_s;               /* cambio maximo de consigna por segundo */
  float deadband;                 /* consignas por debajo -> 0             */
} sumo_params_t;


static inline sumo_params_t sumo_params_default(void)
{
  sumo_params_t p;

  p.dt_ms               = 8;

  p.dist_valid_max_mm   = 800;
  p.dist_attack_mm      = 260;
  p.dist_track_mm       = 700;
  p.target_hold_ms      = 260;

  p.v_attack            = 1.00f;
  p.v_track             = 0.72f;
  p.v_search            = 0.55f;
  p.v_escape            = 0.85f;
  p.v_opening           = 0.80f;

  p.track_kp            = 1.10f;
  p.track_max_diff      = 0.85f;

  p.escape_back_ms      = 300;
  p.escape_turn_ms      = 360;
  p.escape_lockout_ms   = 140;

  p.search_spin_ms      = 520;
  p.search_probe_ms     = 300;
  p.search_turn_ratio   = -0.85f;

  p.opening             = OPENING_CHARGE;
  p.opening_ms          = 420;

  p.slew_per_s          = 25.0f;
  p.deadband            = 0.04f;

  return p;
}

#endif /* SUMO_PARAMS_H */

/* ==========================================================================
 *  strategy.c  --  Cerebro de Gelatina Nuclear
 *  ------------------------------------------------------------------------
 *  LINEA BASE (v0.1.0): maquina de estados reactiva con prioridad absoluta
 *  del borde. Sin memoria del rival, sin modelo del ring, sin aprendizaje.
 *  Es deliberadamente simple: es el punto de partida contra el que se mediran
 *  todas las iteraciones siguientes de la bitacora.
 *
 *  Prioridades, de mayor a menor:
 *     1. No caerse del ring      -> ST_EDGE_ESCAPE
 *     2. Empujar si lo tengo     -> ST_ATTACK
 *     3. Acercarme si lo veo     -> ST_TRACK
 *     4. Encontrarlo             -> ST_SEARCH / ST_OPENING
 *
 *  Este fichero NO incluye cabeceras de Webots ni de ningun microcontrolador.
 * ========================================================================== */

#include "strategy.h"

#include <math.h>
#include <string.h>

#define STRATEGY_VERSION_STR "v0.1.0"

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

/* Angulo de montaje real de los cinco sensores frontales. */
const int16_t SUMO_DIST_ANGLE_CDEG[SUMO_N_DIST] = {
  6000, 3000, 0, -3000, -6000
};

static const char *const STATE_NAMES[ST_COUNT] = {
  "WAIT", "OPENING", "SEARCH", "TRACK", "ATTACK", "EDGE_ESCAPE"
};


/* ==========================================================================
 *  Utilidades numericas
 * ========================================================================== */

static float clampf(float v, float lo, float hi)
{
  return v < lo ? lo : (v > hi ? hi : v);
}

static float slew(float prev, float target, float max_step)
{
  const float d = target - prev;
  if (d >  max_step) return prev + max_step;
  if (d < -max_step) return prev - max_step;
  return target;
}

static uint32_t in_state_ms(const sumo_strategy_t *st)
{
  return st->t_ms - st->t_state_ms;
}

static void enter(sumo_strategy_t *st, sumo_state_t s)
{
  if (st->state == s) return;
  st->state = s;
  st->t_state_ms = st->t_ms;
}


/* ==========================================================================
 *  Percepcion: de lecturas crudas a "donde esta el rival"
 * ==========================================================================
 *  El rumbo se estima como centroide ponderado de los sensores que ven algo:
 *  cuanto mas cerca esta una lectura, mas pesa su angulo de montaje. Con cinco
 *  sensores esto da una resolucion angular muy superior a "cual se dispara",
 *  y sale gratis en computo (cinco multiplicaciones).
 * ========================================================================== */

static void perceive(sumo_strategy_t *st, const sumo_sensors_t *s)
{
  const sumo_params_t *p = &st->p;
  sumo_percept_t *per = &st->per;

  uint32_t w_sum = 0;
  int32_t  w_ang = 0;
  uint16_t nearest = SUMO_DIST_NONE;

  for (int i = 0; i < SUMO_N_DIST; ++i) {
    const uint16_t d = s->dist_mm[i];
    if (d == SUMO_DIST_NONE || d > p->dist_valid_max_mm) continue;

    /* peso lineal inverso: 1 en la cara del robot, 0 al limite util */
    const uint32_t w = (uint32_t)(p->dist_valid_max_mm - d) + 1u;
    w_sum += w;
    w_ang += (int32_t)w * (int32_t)SUMO_DIST_ANGLE_CDEG[i];
    if (d < nearest) nearest = d;
  }

  if (w_sum > 0u) {
    per->target_seen         = true;
    per->target_dist_mm      = nearest;
    per->target_bearing_cdeg = (int16_t)(w_ang / (int32_t)w_sum);
    per->last_seen_ms        = s->t_ms;
  } else if (per->last_seen_ms != 0u &&
             (s->t_ms - per->last_seen_ms) < p->target_hold_ms) {
    /* histeresis: el rival no desaparece porque un sensor parpadee un ciclo */
    per->target_seen = true;
  } else {
    per->target_seen    = false;
    per->target_dist_mm = SUMO_DIST_NONE;
  }

  per->line_mask = 0u;
  for (int i = 0; i < SUMO_N_LINE; ++i)
    if (s->line[i]) per->line_mask |= (uint8_t)(1u << i);
}


/* ==========================================================================
 *  Escape de borde
 * ==========================================================================
 *  La regla mas cara de romper del sumo: el que toca el blanco primero pierde.
 *  Por eso este bloque interrumpe cualquier otro estado, incluso un empuje
 *  ganador. La direccion de huida se deduce de QUE esquinas vieron blanco.
 * ========================================================================== */

static void plan_escape(sumo_strategy_t *st)
{
  const uint8_t m = st->per.line_mask;
  const bool front = (m & SUMO_LINE_FRONT_MASK) != 0u;
  const bool rear  = (m & SUMO_LINE_REAR_MASK)  != 0u;
  const bool left  = (m & SUMO_LINE_LEFT_MASK)  != 0u;
  const bool right = (m & SUMO_LINE_RIGHT_MASK) != 0u;

  if (rear && !front)      st->esc_drive = +1.0f;  /* borde detras: tirar hacia delante */
  else                     st->esc_drive = -1.0f;  /* borde delante o rodeado: atras    */

  if (left && !right)      st->esc_turn = -1.0f;   /* blanco a babor  -> huir a estribor */
  else if (right && !left) st->esc_turn = +1.0f;   /* blanco a estribor -> huir a babor  */
  else                     st->esc_turn = (st->edge_events & 1u) ? +1.0f : -1.0f;

  st->esc_phase = 0u;
  st->edge_events++;
  enter(st, ST_EDGE_ESCAPE);
  st->t_state_ms = st->t_ms;   /* reinicia el cronometro aunque ya estuviera aqui */
}


/* ==========================================================================
 *  Mezclador: (avance, giro) -> consignas de rueda, con rampa y zona muerta
 * ========================================================================== */

static void drive(sumo_strategy_t *st, float fwd, float turn, sumo_actuators_t *a)
{
  const float max_step = st->p.slew_per_s * ((float)st->p.dt_ms / 1000.0f);

  float l = clampf(fwd - turn, -1.0f, 1.0f);
  float r = clampf(fwd + turn, -1.0f, 1.0f);

  l = slew(st->prev_left,  l, max_step);
  r = slew(st->prev_right, r, max_step);

  st->prev_left  = l;
  st->prev_right = r;

  if (fabsf(l) < st->p.deadband) l = 0.0f;
  if (fabsf(r) < st->p.deadband) r = 0.0f;

  a->left  = l;
  a->right = r;
  a->led   = (uint8_t)st->state;
}


/* ==========================================================================
 *  API publica
 * ========================================================================== */

void strategy_init(sumo_strategy_t *st, const sumo_params_t *p)
{
  memset(st, 0, sizeof(*st));
  st->p = p ? *p : sumo_params_default();
  st->state = ST_WAIT;
  st->per.target_dist_mm = SUMO_DIST_NONE;
}


void strategy_step(sumo_strategy_t *st, const sumo_sensors_t *s, sumo_actuators_t *a)
{
  st->t_ms = s->t_ms;
  perceive(st, s);

  /* --- 0. Sin permiso de arranque: quieto y con el lazo reiniciado ------- */
  if (!s->armed) {
    enter(st, ST_WAIT);
    st->prev_left = st->prev_right = 0.0f;
    a->left = a->right = 0.0f;
    a->led  = (uint8_t)ST_WAIT;
    return;
  }
  if (st->state == ST_WAIT) {
    enter(st, ST_OPENING);
    st->t_state_ms = st->t_ms;
  }

  /* --- 1. Prioridad absoluta: el borde ---------------------------------- */
  const bool lockout = (st->t_ms < st->t_edge_clear_ms);
  if (st->per.line_mask != 0u && !lockout && st->state != ST_EDGE_ESCAPE)
    plan_escape(st);

  const sumo_params_t *p = &st->p;
  const float bearing_rad =
      (float)st->per.target_bearing_cdeg / 100.0f * (float)(M_PI / 180.0);

  switch (st->state) {

  /* ---------------------------------------------------------------- */
  case ST_EDGE_ESCAPE: {
    if (st->esc_phase == 0u) {
      /* fase 1: despegarse del borde en linea casi recta */
      drive(st, st->esc_drive * p->v_escape, st->esc_turn * 0.15f, a);
      if (in_state_ms(st) >= p->escape_back_ms) {
        st->esc_phase = 1u;
        st->t_state_ms = st->t_ms;
      }
    } else {
      /* fase 2: reencuadrar hacia el centro del ring */
      drive(st, 0.0f, st->esc_turn * p->v_escape, a);
      if (in_state_ms(st) >= p->escape_turn_ms) {
        st->t_edge_clear_ms = st->t_ms + p->escape_lockout_ms;
        enter(st, ST_SEARCH);
        st->search_probing = false;
      }
    }
    break;
  }

  /* ---------------------------------------------------------------- */
  case ST_OPENING: {
    float fwd = p->v_opening, turn = 0.0f;
    switch (p->opening) {
      case OPENING_CHARGE: turn = 0.0f;  break;
      case OPENING_ARC_L:  turn = 0.45f; break;
      case OPENING_ARC_R:  turn = -0.45f; break;
      case OPENING_SCAN:   fwd = 0.10f; turn = 0.70f; break;
    }
    drive(st, fwd, turn, a);

    /* si aparece el rival, la apertura se abandona al instante */
    if (st->per.target_seen && st->per.target_dist_mm <= p->dist_track_mm)
      enter(st, ST_TRACK);
    else if (in_state_ms(st) >= p->opening_ms)
      enter(st, ST_SEARCH);
    break;
  }

  /* ---------------------------------------------------------------- */
  case ST_SEARCH: {
    if (st->per.target_seen) { enter(st, ST_TRACK); break; }

    /* gira hacia el lado donde se vio al rival por ultima vez */
    const float dir = (st->per.target_bearing_cdeg >= 0) ? 1.0f : -1.0f;

    if (st->search_probing) {
      drive(st, p->v_search, 0.0f, a);
      if (in_state_ms(st) >= p->search_probe_ms) {
        st->search_probing = false;
        st->t_state_ms = st->t_ms;
      }
    } else {
      const float fwd = p->v_search * (1.0f + p->search_turn_ratio);
      drive(st, fwd, dir * p->v_search, a);
      if (in_state_ms(st) >= p->search_spin_ms) {
        st->search_probing = true;
        st->t_state_ms = st->t_ms;
      }
    }
    break;
  }

  /* ---------------------------------------------------------------- */
  case ST_TRACK: {
    if (!st->per.target_seen) {
      enter(st, ST_SEARCH);
      st->search_probing = false;
      break;
    }
    if (st->per.target_dist_mm <= p->dist_attack_mm) { enter(st, ST_ATTACK); break; }

    const float turn = clampf(p->track_kp * bearing_rad,
                              -p->track_max_diff, p->track_max_diff);
    drive(st, p->v_track, turn, a);
    break;
  }

  /* ---------------------------------------------------------------- */
  case ST_ATTACK: {
    if (!st->per.target_seen) {
      enter(st, ST_SEARCH);
      st->search_probing = false;
      break;
    }
    if (st->per.target_dist_mm > p->dist_track_mm) { enter(st, ST_TRACK); break; }

    /* en contacto se corrige poco: girar mucho es perder el empuje */
    const float turn = clampf(p->track_kp * bearing_rad * 0.35f, -0.30f, 0.30f);
    drive(st, p->v_attack, turn, a);
    break;
  }

  /* ---------------------------------------------------------------- */
  case ST_WAIT:
  default:
    drive(st, 0.0f, 0.0f, a);
    break;
  }
}


const char *strategy_state_name(sumo_state_t s)
{
  return (s >= 0 && s < ST_COUNT) ? STATE_NAMES[s] : "?";
}

const char *strategy_version(void)
{
  return STRATEGY_VERSION_STR;
}

/* ==========================================================================
 *  strategy.h  --  API publica del cerebro de Gelatina Nuclear
 *
 *  Toda la inteligencia del robot vive detras de dos funciones. El backend
 *  (Webots, firmware o banco de pruebas) solo rellena sensores, llama a
 *  strategy_step() y aplica los actuadores. Nada mas.
 * ========================================================================== */
#ifndef SUMO_STRATEGY_H
#define SUMO_STRATEGY_H

#include "sumo_types.h"
#include "params.h"

/* Estados de la maquina de combate. El orden importa: se publica como
 * indice en actuators.led para poder depurar desde fuera. */
typedef enum {
  ST_WAIT = 0,      /* inmovil, esperando la senal de arranque       */
  ST_OPENING,       /* jugada de apertura, los primeros ~400 ms      */
  ST_SEARCH,        /* barrido buscando al rival                     */
  ST_TRACK,         /* rival localizado lejos, aproximacion          */
  ST_ATTACK,        /* rival enganchado, empuje maximo               */
  ST_EDGE_ESCAPE,   /* borde detectado, salvar el combate            */
  ST_COUNT
} sumo_state_t;

/* Percepcion derivada, expuesta para telemetria y depuracion. */
typedef struct {
  bool     target_seen;        /* hay rival creible ahora mismo      */
  uint16_t target_dist_mm;     /* distancia al mas cercano           */
  int16_t  target_bearing_cdeg;/* rumbo estimado en centigrados, + = babor */
  uint8_t  line_mask;          /* bits segun enum sumo_line_idx      */
  uint32_t last_seen_ms;       /* instante del ultimo contacto       */
} sumo_percept_t;

typedef struct {
  sumo_params_t  p;
  sumo_state_t   state;
  sumo_percept_t per;

  uint32_t t_ms;             /* reloj recibido en el ultimo paso      */
  uint32_t t_state_ms;       /* instante de entrada al estado actual  */
  uint32_t t_edge_clear_ms;  /* fin de la ventana ciega tras un borde */

  /* sub-fase del escape de borde */
  uint8_t  esc_phase;        /* 0 = retroceder/avanzar, 1 = reencuadrar */
  float    esc_turn;         /* signo y fuerza del giro de escape       */
  float    esc_drive;        /* +1 avanzar, -1 retroceder               */

  /* sub-fase de la busqueda */
  bool     search_probing;

  /* salida anterior, para el limitador de pendiente */
  float    prev_left;
  float    prev_right;

  uint32_t edge_events;      /* contador de bordes vistos, telemetria */
} sumo_strategy_t;

void        strategy_init(sumo_strategy_t *st, const sumo_params_t *p);
void        strategy_step(sumo_strategy_t *st, const sumo_sensors_t *s, sumo_actuators_t *a);
const char *strategy_state_name(sumo_state_t s);
const char *strategy_version(void);

#endif /* SUMO_STRATEGY_H */

